const {
  Document, Packer, Paragraph, TextRun, HeadingLevel,
  AlignmentType, BorderStyle, ShadingType, LevelFormat
} = require('docx');
const fs = require('fs');

const BRAND = "7B4F9E"; // purple accent
const LIGHT_BG = "F5F0FA";
const BORDER_COLOR = "D4C4EC";

function sectionHeader(num, title) {
  return new Paragraph({
    spacing: { before: 360, after: 120 },
    border: {
      bottom: { style: BorderStyle.SINGLE, size: 6, color: BRAND, space: 4 }
    },
    children: [
      new TextRun({ text: `${num}  `, font: "Arial", size: 28, bold: true, color: BRAND }),
      new TextRun({ text: title.toUpperCase(), font: "Arial", size: 28, bold: true, color: "2D2D2D" }),
    ]
  });
}

function questionLabel(text) {
  return new Paragraph({
    spacing: { before: 200, after: 60 },
    children: [
      new TextRun({ text, font: "Arial", size: 22, bold: true, color: "4A4A4A" })
    ]
  });
}

function answerBlock(text) {
  return new Paragraph({
    spacing: { before: 0, after: 160 },
    shading: { fill: LIGHT_BG, type: ShadingType.CLEAR },
    border: {
      left: { style: BorderStyle.SINGLE, size: 12, color: BRAND, space: 8 }
    },
    indent: { left: 200 },
    children: [
      new TextRun({ text, font: "Arial", size: 22, color: "1A1A1A" })
    ]
  });
}

function spacer() {
  return new Paragraph({ spacing: { before: 0, after: 80 }, children: [new TextRun("")] });
}

const sections_data = [
  {
    num: "01",
    title: "Offer Clarity",
    items: [
      {
        q: "What exactly are you selling?",
        a: "A done-with-you revenue growth program for independent med spa owners. Not a course, not a retainer agency, not coaching in the traditional sense. A hands-on partnership where Luxora installs a full revenue operating system inside your business, transfers the knowledge at every step, and stays in your corner for the long game."
      },
      {
        q: "Core outcome in one sentence:",
        a: "We help independent med spa owners generating $500K to $2M recover the revenue they're already losing, build the systems they've never had, and grow without adding more to their plate."
      },
      {
        q: "Guarantee positioning:",
        a: "Confidence-based guarantee built around the Revenue Leak Audit. We will find the money you're already leaving on the table before we ask you to invest in anything new. Not views-based. Not hype. Just a promise to show you the leak first."
      },
      {
        q: "Real outcome we care about:",
        a: "Revenue. Specifically: retained revenue, increased lifetime value, higher average transaction, more booked appointments from existing clients, and front desk conversions that actually close."
      }
    ]
  },
  {
    num: "02",
    title: "Target Audience",
    items: [
      {
        q: "Ideal client:",
        a: "Independent med spa owner. Not a franchise. Owner-operator who built their business themselves, likely from an aesthetic injector or nurse practitioner background. Generating $500K to $2M annually. Established but stuck. Has proven the business works, has clients who love them, probably has a small team, and is still showing up to every shift, handling every decision, and wondering why growth feels so hard when they are already this good at what they do."
      },
      {
        q: "Who this is NOT for:",
        a: "Owners who want someone to run their marketing with no involvement. Owners who believe posting more on Instagram is the answer. Owners not willing to have honest conversations about what is and is not working. Anyone wanting fast hacks, not real infrastructure. Franchise operators or owners with a corporate team already in place. Anyone generating under $500K still in early survival phase."
      },
      {
        q: "Biggest frustrations right now:",
        a: "Tried marketing agencies, got pretty content with no measurable return. Ran ads and either burned money or got leads who did not convert. Front desk is friendly but not trained to sell. Launched memberships that never gained traction. Best clients are loyal but stagnant. They are the highest-paid employee in their own business and also the most trapped. They feel like they should be further along by now."
      },
      {
        q: "What they secretly want but would not say out loud:",
        a: "They want their business to run without them being in every transaction. To walk into their spa and see things moving without managing every person, every follow-up, every decision. To feel like a CEO, not a glorified injector. To trust that when they take a vacation, revenue does not drop. And underneath all of that, they want someone to look at their business and tell them they have not been doing it wrong. They just have not had the right systems."
      }
    ]
  },
  {
    num: "03",
    title: "Differentiation",
    items: [
      {
        q: "vs. typical social media agency:",
        a: "Agencies create content. Luxora installs a revenue operating system. The deliverable is not a post or a reel. It is a membership program that actually fills, a package architecture that increases average transaction, a trained front desk that converts, a CRM that follows up automatically, and a retention engine that keeps clients coming back and spending more. Those are business assets, not marketing outputs."
      },
      {
        q: "vs. freelancers:",
        a: "Freelancers own one piece. A copywriter writes emails. A social media manager posts content. A coach gives advice. Luxora is cross-functional, meaning strategy, systems, training, technology, partnerships, and marketing all move together. No freelancer can install all of that."
      },
      {
        q: "The mechanism:",
        a: "It starts with the Revenue Leak Audit. Before anything else is recommended or purchased, Luxora maps exactly where the business is losing money right now. Most owners discover $50K to $200K in recoverable revenue before any new marketing is run. That audit is the foundation. Everything built after it is built on real data from that specific business, not a generic playbook."
      },
      {
        q: "Why clients succeed where others fail:",
        a: "Because Luxora does not hand them a framework and walk away. Done-with-you means Luxora is in the work alongside the owner, with monthly accountability, real implementation support, and a system designed to transfer ownership to the client over time so they are more capable at the end of the engagement than at the beginning."
      }
    ]
  },
  {
    num: "04",
    title: "Proof",
    items: [
      {
        q: "Top case study: best result",
        a: "[ADD YOUR BEST CASE STUDY HERE: client name or type, situation before Luxora, specific result, revenue recovered or grown]"
      },
      {
        q: "Top case study: fastest result",
        a: "[ADD YOUR FASTEST WIN: how quickly did a client see measurable results? What specifically changed in 30 to 60 days?]"
      },
      {
        q: "Top case study: most dramatic transformation",
        a: "[ADD YOUR BEFORE/AFTER: what did the business look like before Luxora vs. after? What was the owner experiencing? What changed?]"
      },
      {
        q: "Authority signals:",
        a: "Tracy Olson of Aesthetic Injector Academy (injectorsschool.com) as a strategic partner. Deep program library including 90-Day Growth Engine roadmap, membership, package, and LTV playbooks. Bethany's background in medspa operations, Meta and Google advertising for aesthetics, GoHighLevel CRM optimization, and AI automation."
      }
    ]
  },
  {
    num: "05",
    title: "Fulfillment and Ease",
    items: [
      {
        q: "Time commitment per week:",
        a: "Light. Two to four hours per week in the active phase, less once systems are installed. The heavy lifting on systems, scripting, CRM setup, and training infrastructure is handled by the Luxora team. The owner's job is to show up to scheduled sessions, make decisions, and lead their team through the changes."
      },
      {
        q: "What Luxora handles:",
        a: "Revenue Leak Audit and Market Blueprint. Membership and package architecture design. Staff sales training scripts and playbooks. CRM setup and AI follow-up sequences. Partnership identification and outreach frameworks. Reputation engine design. Marketing strategy and content direction. Bi-weekly accountability calls and implementation support throughout."
      },
      {
        q: "What the client handles:",
        a: "Leading their team through the changes. Showing up to calls. Making decisions about their business. Executing the staff training using Luxora-built tools and scripts."
      },
      {
        q: "How fast they see results:",
        a: "The Revenue Leak Audit delivers findings immediately. Most clients begin recovering revenue in the first 30 to 60 days simply by plugging the gaps identified in the audit. Full program results compound over 90 days and beyond as each system layer is installed and activated."
      }
    ]
  },
  {
    num: "06",
    title: "Pricing and Objections",
    items: [
      {
        q: "Pricing positioning:",
        a: "Premium. Not a $97 course or a $500 per month retainer. Financing available through Klarna and Affirm to remove the upfront barrier without compromising the premium positioning. Preferred engagement is 12 months or longer because the system has multiple phases and the compounding happens over time, not in a sprint."
      },
      {
        q: "Objection 1: 'I have tried agencies before and it did not work'",
        a: "The most common objection. The response is the audit mechanism: Luxora does not start with marketing. It starts by finding what is already broken. That is a fundamentally different entry point than any agency they have hired. The Revenue Leak Audit is proof before a single dollar is invested."
      },
      {
        q: "Objection 2: 'I cannot afford it right now'",
        a: "Usually means they do not yet see the ROI clearly. The answer lives in the audit findings. If the audit reveals $80K in recoverable annual revenue, the investment reframes itself immediately. Financing through Klarna and Affirm is also available."
      },
      {
        q: "Objection 3: 'I do not have time for another thing'",
        a: "This is fear of complexity. The answer is the done-with-you model and the specific time commitment. The owner is not project managing this. They are participating in it while Luxora drives it. Two to four hours per week."
      }
    ]
  },
  {
    num: "07",
    title: "Call to Action",
    items: [
      {
        q: "Next step:",
        a: "Book a call directly with Bethany. Not an application form with a two-week wait. A direct, qualified conversation. The discovery call uses the live Revenue Leak Scan tool at revleak.theluxoracollective.co so the prospect experiences value in real time before any decision is made."
      },
      {
        q: "How the CTA should feel:",
        a: "Exclusive but accessible. Not aggressive. No countdown timers or fake scarcity. The tone should feel like: if this is your situation, there is a clear next step and we will take it together. The feminine funnel framework, which is trust-building, slow pacing, and permission-based transitions, should be seeded in the CTA language so the call experience feels like a natural continuation of the VSL, not a gear shift."
      }
    ]
  },
  {
    num: "08",
    title: "Tone",
    items: [
      {
        q: "Overall tone:",
        a: "Calm authority with emotional precision. Not aggressive. Not dominant. Not corporate. This owner has been talked at by vendors for years. What moves her is someone who clearly understands her world, names what she has been feeling without her having to explain it, and presents a path forward that feels designed for her specifically, not mass-produced."
      },
      {
        q: "VSL through-line:",
        a: "She did not build this business to become the manager of her own chaos. She built it to give people transformation. Luxora makes the business reflect what she actually built it for."
      },
      {
        q: "Humor and warmth:",
        a: "Warmth yes. Humor no. This is about her business, her income, her identity as an owner. The emotional register is: I see you. I know exactly what is happening. And here is how we fix it."
      }
    ]
  }
];

const children = [];

// Title block
children.push(
  new Paragraph({
    spacing: { before: 0, after: 80 },
    children: [
      new TextRun({ text: "THE LUXORA COLLECTIVE", font: "Arial", size: 28, bold: true, color: BRAND })
    ]
  }),
  new Paragraph({
    spacing: { before: 0, after: 60 },
    children: [
      new TextRun({ text: "VSL Foundation Document", font: "Arial", size: 36, bold: true, color: "1A1A1A" })
    ]
  }),
  new Paragraph({
    spacing: { before: 0, after: 400 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: BRAND, space: 4 } },
    children: [
      new TextRun({ text: "Questions and Answers for Script Development", font: "Arial", size: 22, color: "6B6B6B", italics: true })
    ]
  })
);

// Sections
for (const section of sections_data) {
  children.push(sectionHeader(section.num, section.title));
  for (const item of section.items) {
    children.push(questionLabel(item.q));
    children.push(answerBlock(item.a));
    children.push(spacer());
  }
}

const doc = new Document({
  styles: {
    default: {
      document: { run: { font: "Arial", size: 22 } }
    }
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1080, right: 1260, bottom: 1080, left: 1260 }
      }
    },
    children
  }]
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync("/home/claude/Luxora_VSL_Foundation.docx", buffer);
  console.log("Done");
});

