const {
  Document, Packer, Paragraph, TextRun, BorderStyle, ShadingType,
  AlignmentType, LevelFormat, WidthType, PageBreak
} = require('docx');
const fs = require('fs');

const PURPLE = "6B3FA0";
const LIGHT_BG = "F5F0FA";
const DARK = "1A1A1A";
const MID = "4A4A4A";
const MUTED = "7A7A7A";

function p(children, opts = {}) {
  return new Paragraph({ children, ...opts });
}

function t(text, opts = {}) {
  return new TextRun({ text, font: "Arial", ...opts });
}

function heading(text) {
  return p([t(text, { size: 26, bold: true, color: PURPLE })], {
    spacing: { before: 400, after: 120 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: "D4C4EC", space: 4 } }
  });
}

function dirNote(text) {
  return p([t(text, { size: 20, italics: true, color: MUTED })], {
    spacing: { before: 80, after: 80 },
    shading: { fill: "F0F0F0", type: ShadingType.CLEAR },
